// Case study detail page, one per entry in ../data.ts. Hand-written (not generated by scripts/gen_page.py);
// uses the .csp-* case study styles in src/styles/pages.css.
import type { Metadata } from "next";
import Script from "next/script";
import { notFound } from "next/navigation";
import { SiteNav, SiteFooter } from "@/components/SiteChrome";
import { PageHero } from "@/components/PageHero";
import { CASE_STUDIES, getCaseStudy } from "../data";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH || "";

export const dynamicParams = false;

export function generateStaticParams() {
  return CASE_STUDIES.map((c) => ({ slug: c.slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const cs = getCaseStudy((await params).slug);
  if (!cs) return {};
  return {
    title: `${cs.name} case study | ${cs.cardStat} | Adalytical`,
    description: cs.summary,
    alternates: { canonical: `/case-studies/${cs.slug}/` },
  };
}

const Arrow = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2"><path d="M5 12h14M13 6l6 6-6 6" strokeLinecap="round" strokeLinejoin="round"/></svg>
);
const Check = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6"><path d="M20 6 9 17l-5-5" strokeLinecap="round" strokeLinejoin="round"/></svg>
);

export default async function CaseStudyPage({ params }: { params: Promise<{ slug: string }> }) {
  const cs = getCaseStudy((await params).slug);
  if (!cs) notFound();
  // "More case studies": these two first; on their own pages the next one in MORE_PICKS fills in.
  const MORE_PICKS = ["lokolash", "peninsula-heat-pumps", "watch-factory", "bushdoof-lighting"];
  const more = MORE_PICKS.filter((s) => s !== cs.slug).slice(0, 2).map((s) => CASE_STUDIES.find((c) => c.slug === s)!); // two cards fill the 2-column grid

  return (
    <>
      <SiteNav />

{/* ============ HERO ============ */}
<PageHero
  back={{ href: "/case-studies/", text: "All case studies" }}
  title={<>{cs.title.lead} <span className="accent">{cs.title.accent}</span></>}
  sub={cs.summary}
  actions={<><a href={`${BASE}/book/`} className="btn-p">Get Your Free Growth Plan</a></>}
/>

{/* ============ STORY ============ */}
<section className="sec-cream">
  <div className="csp-body rvsec">
    <aside className="csp-side rv">
      <div className="csp-glance">
        <div className="csp-glance-img">{cs.image && <img src={`${BASE}/images/${cs.image}`} alt={cs.name} />}</div>
        <dl className="csp-glance-list">
          <div><dt>Client</dt><dd>{cs.name}</dd></div>
          <div><dt>Industry</dt><dd>{cs.tag}</dd></div>
          <div><dt>Channel</dt><dd>Google Ads</dd></div>
                    {cs.services && <div><dt>Services</dt><dd>{cs.services.join(", ")}</dd></div>}
        </dl>
        <a href={`${BASE}/book/`} className="btn-p csp-glance-cta">Get Your Free Growth Plan <Arrow /></a>
      </div>
    </aside>

    <div className="csp-prose rv">
      <span className="lbl first">The challenge</span>
      {cs.challenge.map((p) => <p key={p}>{p}</p>)}

      <span className="lbl">Our strategy</span>
      {cs.strategy.intro?.map((p) => <p key={p}>{p}</p>)}
      {cs.strategy.points && (
        <ul className="csp-steps">
          {cs.strategy.points.map((pt) => (
            <li key={pt.title}><span className="csp-step-ic"><Check /></span><div><strong>{pt.title}</strong><span>{pt.body}</span></div></li>
          ))}
        </ul>
      )}

      <span className="lbl" id="results">The results</span>
      <p>{cs.results.body}</p>
      <div className="csp-results">
        {cs.results.stats.map((s) => (
          <div className={`csp-result${s.value ? "" : " csp-result-text"}`} key={s.label}>{s.value && <strong>{s.value}</strong>}<span>{s.label}</span></div>
        ))}
      </div>
    </div>
  </div>
</section>

{/* ============ MORE CASE STUDIES ============ */}
<section className="csp-more rvsec">
  <div className="ctr">
    <div className="csp-more-head rv">
      <div>
        <span className="sec-tag">More results</span>
        <h2>More case studies</h2>
      </div>
      <a href={`${BASE}/case-studies/`} className="svc-link">View all case studies <Arrow /></a>
    </div>
    <div className="cs-index rv">
      {more.map((c) => (
        <a href={`${BASE}/case-studies/${c.slug}/`} className="csx" key={c.slug}>
          <div className="csx-img">{c.image && <img src={`${BASE}/images/${c.image}`} alt={c.name} />}<span className="csx-stat">{c.cardStat}</span></div>
          <div className="csx-body">
            <span className="csx-tag">{c.tag}</span>
            <h3>{c.name}</h3>
            <p>{c.cardBlurb}</p>
            <span className="csx-more">Read story <Arrow /></span>
          </div>
        </a>
      ))}
    </div>
  </div>
</section>

{/* ============ FINAL CTA ============ */}
<section className="sec sec-cream cta rvsec" id="book">
  <div className="ctr">
    <div className="cta-card rv">
      <span className="sec-tag">Get started</span>
      <h2>Your account could be the next case study.</h2>
      <p>Book a free audit and we’ll map out exactly where your Google Ads are leaving money on the table.</p>
      <div className="cta-btns"><a href={`${BASE}/book/`} className="btn-p">Get Your Free Growth Plan <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" width="18" height="18"><path d="M5 12h14M13 6l6 6-6 6" strokeLinecap="round" strokeLinejoin="round"/></svg></a></div>
      <div className="cta-micro" style={{'justifyContent':'center'}}>
        <span className="cm-i"><Check />Free &amp; no obligation</span>
        <span className="cm-sep"></span>
        <span className="cm-i"><Check />No lock-in contracts</span>
        <span className="cm-sep"></span>
        <span className="cm-i"><Check />Ex-Google Ads team</span>
      </div>
    </div>
  </div>
</section>

      <SiteFooter />
      <Script src={`${BASE}/assets/site.js`} strategy="afterInteractive" />
    </>
  );
}
